-- generated by tools/gencatalog, do not edit by hand

CREATE TABLE project_roles (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    code VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    description VARCHAR(512),
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE project_role_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    project_role_id BIGINT       NOT NULL REFERENCES project_roles(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_project_role_revisions_revision
        UNIQUE (project_role_id, revision_number)
);

CREATE UNIQUE INDEX uq_project_roles_code
    ON project_roles (code);

CREATE INDEX idx_project_roles_active
    ON project_roles (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_project_role_revisions_project_role_id
    ON project_role_revisions (project_role_id);

CREATE INDEX idx_project_role_revisions_covering_agg
    ON project_role_revisions (project_role_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_project_role_revisions_changed_at
    ON project_role_revisions (changed_at);

CREATE OR REPLACE VIEW v_expanded_project_role AS
SELECT
    t.id,
    t.code,
    t.name,
    t.description,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM project_roles t
LEFT JOIN (
    SELECT
        project_role_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM project_role_revisions
    GROUP BY project_role_id
) agg ON agg.project_role_id = t.id;

COMMENT ON TABLE project_roles IS
    'Project roles used by the planning of work. Stores the current state of each record.';

COMMENT ON TABLE project_role_revisions IS
    'Immutable audit log of changes applied to project_roles. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_project_role IS
    'Read-only view that enriches each project_role with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
